CREATE POLICY "Editorial view newsroom images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'newsroom-images' AND private.is_editorial(auth.uid()));
CREATE POLICY "Editorial upload newsroom images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'newsroom-images' AND private.is_editorial(auth.uid()));
CREATE POLICY "Editorial update newsroom images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'newsroom-images' AND private.is_editorial(auth.uid()));
CREATE POLICY "Editorial delete newsroom images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'newsroom-images' AND private.is_editorial(auth.uid()));